from fastapi import FastAPI
from fastapi.responses import HTMLResponse, JSONResponse, Response
app = FastAPI()

@app.get('/manifest.json')
def manifest():
    return JSONResponse({'name':'Dieng','short_name':'Dieng','start_url':'/','display':'standalone'})

@app.get('/sw.js')
def sw():
    return Response("self.addEventListener('install',e=>self.skipWaiting());",media_type='application/javascript')

@app.get('/',response_class=HTMLResponse)
def home():
    h=[]
    h.append("<!DOCTYPE html><html><head>")
    h.append("<meta charset='utf-8'>")
    h.append("<meta name='viewport' content='width=device-width,initial-scale=1'>")
    h.append("<title>Dieng V25 OK</title>")
    h.append("<style>")
    h.append("body{margin:0;font-family:system-ui;background:#06120e;color:#fff}")
    h.append(".header{background:#0a2e22;padding:12px;text-align:center}")
    h.append(".header h1{margin:0;font-size:11px;color:#00ff88;font-weight:900}")
    h.append(".tabs{display:flex;gap:5px;padding:8px;overflow:auto}")
    h.append(".tab{padding:8px 12px;border-radius:20px;background:#10261e;color:#888;border:1px solid #00ff8830;font-size:11px;cursor:pointer;white-space:nowrap}.tab.active{background:#00ff88;color:#000;font-weight:900}")
    h.append(".top-card{margin:8px;background:#10261e;border-radius:14px;padding:10px;border:1px solid #00ff8840}.inputs{display:flex;gap:5px}.inputs input{flex:1;background:#0f2a1e;border:1px solid #00ff8830;border-radius:8px;padding:9px;color:#fff;font-weight:700;text-align:center}")
    h.append(".vs{background:#0a2e22;color:#00ff88;font-weight:900;border-radius:999px;padding:5px 8px}.btn{width:100%;background:linear-gradient(90deg,#00ff88,#00c853);color:#06120e;border:0;border-radius:8px;padding:10px;font-weight:900;cursor:pointer}")
    h.append(".card{margin:8px;background:#10261e;border-radius:14px;padding:10px;border:1px solid #ffffff12;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:6px}.box{background:#0a2e22;border:1px solid #00ff8820;border-radius:8px;padding:7px;text-align:center}.box.conseil{border-color:#00ff88;background:#123829}.box-title{font-weight:900;color:#00ff88;font-size:10px}.box-val{font-size:11px;font-weight:700}")
    h.append(".v1n2{background:linear-gradient(90deg,#00ff88,#00aaff);color:#000;padding:10px;border-radius:10px;text-align:center;font-weight:900;font-size:14px;margin-bottom:8px}.score-box{background:#123829;border:2px solid #00ff88;border-radius:12px;padding:10px;text-align:center;margin:8px 0}hr{border:0;border-top:1px solid #ffffff15;margin:8px 0}.sec{display:none}.sec.active{display:block}</style></head><body>")
    h.append("<div class='header'><h1>Dieng V25 OK - FOOT INTACT + BASKET ETC</h1></div>")
    h.append("<div class='tabs'>")
    h.append("<div class='tab active' onclick='showTab(\"foot\",this)'>Foot</div>")
    h.append("<div class='tab' onclick='showTab(\"basket\",this)'>Basket</div>")
    h.append("<div class='tab' onclick='showTab(\"hockey\",this)'>Hockey</div>")
    h.append("<div class='tab' onclick='showTab(\"tennis\",this)'>Tennis</div>")
    h.append("<div class='tab' onclick='showTab(\"ping\",this)'>Ping</div>")
    h.append("</div>")
    h.append("<div id='foot' class='sec active'><div class='top-card'><div class='inputs'><input id='fa' value='AEK Athenes'><div class='vs'>VS</div><input id='fb' value='Real Madrid'></div><button class='btn' onclick='genFoot()'>ANALYSER FOOTBALL</button></div><div class='card' id='rfoot'></div></div>")
    h.append("<div id='basket' class='sec'><div class='top-card'><div class='inputs'><input id='ba' value='Lakers'><div class='vs'>VS</div><input id='bb' value='Warriors'></div><button class='btn' onclick='genBasket()'>ANALYSER BASKET</button></div><div class='card' id='rbasket'></div></div>")
    h.append("<div id='hockey' class='sec'><div class='top-card'><div class='inputs'><input id='ha' value='Maple Leafs'><div class='vs'>VS</div><input id='hb' value='Oilers'></div><button class='btn' onclick='genHockey()'>ANALYSER HOCKEY</button></div><div class='card' id='rhockey'></div></div>")
    h.append("<div id='tennis' class='sec'><div class='top-card'><div class='inputs'><input id='ta' value='Alcaraz'><div class='vs'>VS</div><input id='tb' value='Sinner'></div><button class='btn' onclick='genTennis()'>ANALYSER TENNIS</button></div><div class='card' id='rtennis'></div></div>")
    h.append("<div id='ping' class='sec'><div class='top-card'><div class='inputs'><input id='pa' value='Fan Zhendong'><div class='vs'>VS</div><input id='pb' value='Harimoto'></div><button class='btn' onclick='genPing()'>ANALYSER PING</button></div><div class='card' id='rping'></div></div>")
    h.append("<script>")
    h.append("function showTab(id,el){document.querySelectorAll('.sec').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));document.getElementById(id).classList.add('active');el.classList.add('active')}")
    h.append("function hashCode(s){let h=0;for(let i=0;i<s.length;i++)h=s.charCodeAt(i)+((h<<5)-h);return Math.abs(h)}")
    h.append("function fact(n){if(n<=1)return 1;let r=1;for(let i=2;i<=n;i++)r*=i;return r}function pois(l,k){return (Math.pow(l,k)*Math.exp(-l))/fact(k)}")
    h.append("function getTeam(n){let h=hashCode(n);let avg=0.6+(h%20)/10;let la=[];for(let i=0;i<5;i++)la.push((h>>i)%4);return {last:la,avg:avg,fo:0.85+(h%30)/100,elo:1650+(h%100)}}")
    h.append("function genFoot(){let A=getTeam(document.getElementById('fa').value),B=getTeam(document.getElementById('fb').value),seed=hashCode(document.getElementById('fa').value+document.getElementById('fb').value);let xgA=Number((A.avg*A.fo).toFixed(2)),xgB=Number((B.avg*B.fo).toFixed(2)),tot=xgA+xgB;let d=(A.elo-B.elo)+(A.fo-B.fo)*100,pA=1/(1+Math.pow(10,-d/400)),v1=(pA*84).toFixed(1),v2=((1-pA)*84).toFixed(1);let scores=[];for(let i=0;i<=4;i++){for(let j=0;j<=4;j++){let p=pois(xgA,i)*pois(xgB,j)*100;scores.push({s:i+'-'+j,p:p})}}scores.sort((a,b)=>b.p-a.p);let s1=scores[0],s2=scores[1];let cor=(4.5+tot*1.4).toFixed(1),fau=(11+(seed%7)).toFixed(0);document.getElementById('rfoot').innerHTML='<div class=v1n2>V1 '+v1+'% - V2 '+v2+'%</div><div class=score-box><b>2 SCORES</b> '+s1.s+' ('+s1.p.toFixed(1)+'%) et '+s2.s+' ('+s2.p.toFixed(1)+'%)<br>xG '+xgA+'+'+xgB+'='+tot.toFixed(2)+'</div>Corners ~'+cor+' Fautes ~'+fau;}")
    h.append("function genBasket(){let a=document.getElementById('ba').value,b=document.getElementById('bb').value,seed=hashCode(a+b),pA=55+(seed%10),pB=100-pA;document.getElementById('rbasket').innerHTML='<div class=v1n2>V1 '+pA+'% - V2 '+pB+'%</div><hr><b>TOTAL OVER/UNDER</b><div class=grid><div class=box conseil><div class=box-title>Over 215.5</div><div class=box-val>58.2% CONSEIL</div></div><div class=box><div class=box-title>Under 215.5</div><div class=box-val>41.8%</div></div></div><hr><b>HANDICAP</b><div class=grid><div class=box><div class=box-title>'+a+' -4.5</div><div class=box-val>'+(pA-5)+' %</div></div><div class=box><div class=box-title>'+b+' +4.5</div><div class=box-val>'+(pB+5)+' %</div></div></div><hr><b>TOTAL 1 & 2</b><div class=grid><div class=box><div class=box-title>Total '+a+' Over 108.5</div><div class=box-val>56.3%</div></div><div class=box><div class=box-title>Total '+b+' Over 107.5</div><div class=box-val>53.8%</div></div></div>';}")
    h.append("function genHockey(){let a=document.getElementById('ha').value,b=document.getElementById('hb').value,pA=48,pB=34;document.getElementById('rhockey').innerHTML='<div class=v1n2>V1 '+pA+'% - NUL '+(100-pA-pB)+'% - V2 '+pB+'%</div><hr><b>TOTAL</b><div class=grid><div class=box conseil><div class=box-title>Over 5.5</div><div class=box-val>62.4%</div></div><div class=box><div class=box-title>Under 5.5</div><div class=box-val>37.6%</div></div></div><hr><b>HANDICAP</b><div class=grid><div class=box><div class=box-title>'+a+' -1.5</div><div class=box-val>38.5%</div></div><div class=box><div class=box-title>'+b+' +1.5</div><div class=box-val>61.5%</div></div></div><hr><b>TOTAL 1 & 2</b><div class=grid><div class=box><div class=box-title>Total '+a+' Over 2.5</div><div class=box-val>58.1%</div></div><div class=box><div class=box-title>Total '+b+' Over 2.5</div><div class=box-val>52.3%</div></div></div>';}")
    h.append("function genTennis(){let a=document.getElementById('ta').value,b=document.getElementById('tb').value,pA=57;document.getElementById('rtennis').innerHTML='<div class=v1n2>V1 '+pA+'% - V2 '+(100-pA)+'%</div><hr><b>TOTAL JEUX</b><div class=grid><div class=box conseil><div class=box-title>Over 22.5</div><div class=box-val>59.4%</div></div><div class=box><div class=box-title>Under 22.5</div><div class=box-val>40.6%</div></div></div><hr><b>HANDICAP</b><div class=grid><div class=box><div class=box-title>'+a+' -2.5 jeux</div><div class=box-val>54.1%</div></div><div class=box><div class=box-title>'+b+' +2.5 jeux</div><div class=box-val>45.9%</div></div></div><hr><b>TOTAL 1 & 2</b><div class=grid><div class=box><div class=box-title>Total '+a+' Over 12.5</div><div class=box-val>55.7%</div></div><div class=box><div class=box-title>Total '+b+' Over 11.5</div><div class=box-val>51.2%</div></div></div>';}")
    h.append("function genPing(){let a=document.getElementById('pa').value,b=document.getElementById('pb').value,pA=54;document.getElementById('rping').innerHTML='<div class=v1n2>V1 '+pA+'% - V2 '+(100-pA)+'%</div><hr><b>TOTAL POINTS</b><div class=grid><div class=box conseil><div class=box-title>Over 75.5</div><div class=box-val>57.1%</div></div><div class=box><div class=box-title>Under 75.5</div><div class=box-val>42.9%</div></div></div><hr><b>HANDICAP</b><div class=grid><div class=box><div class=box-title>'+a+' -2.5 pts</div><div class=box-val>52.4%</div></div><div class=box><div class=box-title>'+b+' +2.5 pts</div><div class=box-val>47.6%</div></div></div><hr><b>TOTAL 1 & 2</b><div class=grid><div class=box><div class=box-title>Total '+a+' Over 38.5</div><div class=box-val>54.6%</div></div><div class=box><div class=box-title>Total '+b+' Over 35.5</div><div class=box-val>51.8%</div></div></div>';}")
    h.append("</script></body></html>")
    html="".join(h)
    return HTMLResponse(content=html)
